def solve(nums, k):
	def partition(start, end):
		pivot = nums[end]
		i = start
		for j in range(start, end):
			if nums[j] <= pivot:
				nums[i], nums[j] = nums[j], nums[i]
				i += 1
		nums[i], nums[end] = nums[end], nums[i]
		return i

	def quickselect(start, end, k):
		if start == end:
			return nums[start]
		pivot_index = partition(start, end)
		if k == pivot_index - start + 1:
			return nums[pivot_index]
		elif k < pivot_index - start + 1:
			return quickselect(start, pivot_index - 1, k)
		else:
			return quickselect(pivot_index + 1, end, k - (pivot_index - start + 1))

	return quickselect(0, len(nums) - 1, k)
