def solve(intervals):
    if not intervals:
        return 0

    # Sort intervals by their end points
    intervals.sort(key=lambda x: x[1])

    removed = 0
    end = -float('inf')

    for start, curr_end in intervals:
        if start < end:
            removed += 1
        else:
            end = curr_end

    # The number of intervals to remove is the total intervals minus the number of non-overlapping intervals kept
    return len(intervals) - (len(intervals) - removed)
```

